package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.*;
import com.openggf.game.soniccd.objects.*;
import com.openggf.game.soniccd.player.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;
import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;
/** Tests FIRST, Java UNRUN. Actual C/D data and source body, labelled constructed complete
 * pure component values/public-pool ingress. No actual World/native route/Frame invocation claim. */
class TestCdR13BossBodyJoin {
    @Test void oldThreeFieldResponseAndTouchContextsAndOldStepRemainStrict()throws Exception {assertEquals(3,CdPlayerBody.ResponseContext.class.getRecordComponents().length);assertEquals(3,CdPlayerBody.TouchContext.class.getRecordComponents().length);for(var a:TestCdR13FutureAssets.retail().all()){var h=new H(a,0xFC,2);assertThrows(CdPlayerBody.UnsupportedTouchHandler.class,()->h.body.step(h.state,h.env,Optional.of(h.touch),Optional.empty(),Optional.empty(),Optional.empty()));assertEquals(2,h.pool.pool().state(50).unsignedByte(COLLISION_STATUS));}}
    @Test void genuineSelectedBossSpecialHealthyDamageHasDistinctFinalOutcomeWithoutReplay()throws Exception {for(var a:TestCdR13FutureAssets.retail().all())for(int raw=0xFC;raw<=0xFF;raw++){var h=new H(a,raw,2);var before=h.pool.capture();var out=h.run(h.marker());var effect=one(out);assertInstanceOf(CdPlayerTouchResponse.BossSpecialCompleted.class,effect.result());assertEquals(5,effect.result().values().changedSlots().getFirst().unsignedByte(COLLISION_STATUS));assertEquals(0,effect.result().values().changedSlots().getFirst().unsignedByte(COLLISION_TYPE));assertEquals(CdPlayerTouchResponse.Exit.DAMAGE_ENEMY,effect.result().commonResult().orElseThrow().exit());assertTrue(out.effects().stream().noneMatch(x->x instanceof CdPlayerBody.ObjectTouchResponse));assertEquals(before.pool().slots(),h.pool.capture().pool().slots());}}
    @Test void inactiveBossContextPublishesNoFabricatedCommonExit()throws Exception {for(var a:TestCdR13FutureAssets.retail().all())for(int flag:new int[]{0,2,255}){var h=new H(a,0xFC,2,flag);var effect=one(h.run(h.marker()));assertTrue(effect.result().commonResult().isEmpty());assertTrue(effect.result().values().calls().isEmpty());assertTrue(effect.result().values().changedSlots().isEmpty());}}
    @Test void staleSnapshotMarkerFailsAtSelectedBossBeforeResponse()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var h=new H(a,0xFC,2);var marker=new CdPlayerBody.BossSpecialContext(h.response,h.pool.pool().capture(),1);assertThrows(IllegalArgumentException.class,()->h.run(marker));assertEquals(2,h.pool.pool().state(50).unsignedByte(COLLISION_STATUS));}}
    @Test void equalDifferentResponseMarkerDoesNotAuthorizeSelectedBoss()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var h=new H(a,0xFC,2);var other=CdPlayerTouchResponse.fromAct3FutureAssets(CdR13PlayerCollisionAssets.fromAssets(a));var marker=new CdPlayerBody.BossSpecialContext(other,h.cut,1);assertThrows(IllegalArgumentException.class,()->h.run(marker));}}
    @Test void markerBossFightMustMatchTheActualCurrentBodyBoundsByte()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var h=new H(a,0xFC,2);assertThrows(IllegalArgumentException.class,()->h.run(new CdPlayerBody.BossSpecialContext(h.response,h.cut,0)));assertThrows(IllegalArgumentException.class,()->new CdPlayerBody.BossSpecialContext(h.response,h.cut,256));}}
    @Test void normalSpecialFlagHandlerStillUsesOriginalResponsePath()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var h=new H(a,0xDF,2);var out=h.run(h.marker());assertTrue(out.effects().stream().noneMatch(x->x instanceof CdPlayerBody.ObjectBossTouchResponse));assertTrue(out.effects().stream().anyMatch(x->x instanceof CdPlayerBody.ObjectTouchResponse));}}
    @Test void emptySelectedScanDoesNotReadForeignMarker()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var h=new H(a,0xFC,2);h.pool.pool().deleteObject(50);h.refresh();var bad=new CdPlayerBody.BossSpecialContext(CdPlayerTouchResponse.fromAct3FutureAssets(CdR13PlayerCollisionAssets.fromAssets(a)),new CdObjectPool().capture(),255);var out=h.run(bad);assertTrue(out.effects().stream().noneMatch(x->x instanceof CdPlayerBody.ObjectBossTouchResponse));}}
    @Test void commonFailureRetainsInheritedPureBodyThrowAtomicLimitAndDoesNotInventResult()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var h=new H(a,0xFC,0);var g=h.env.movement().globals();var m=h.env.movement();h.env=new CdPlayerBody.Environment(new CdPlayerMovement.Environment(m.physics(),m.bounds(),m.gates(),new CdPlayerMovement.Globals(g.lookMode(),g.cameraYCentre(),g.primaryAngle(),g.secondaryAngle(),g.boredTimer(),1,g.debugAngle(),g.debugAngleShift(),g.debugQuadrant(),g.debugFloorDistance())),h.env.controls(),h.env.globals(),h.env.dynamicSlots());var before=h.pool.capture();var e=assertThrows(CdPlayerTouchResponse.UnsupportedResponse.class,()->h.run(h.marker()));assertEquals(CdPlayerTouchResponse.UnsupportedBoundary.ODD_ENEMY_POINTS_ADDRESS,e.boundary());assertEquals(before.pool().slots(),h.pool.capture().pool().slots());}}
    @Test void nativeBodyTouchGateKeepsOptInContextUnsampled()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var h=new H(a,0xFC,2);var m=h.state.motion();h.state=new CdPlayerBody.State(new CdPlayerMotionState(m.centreX16_16(),m.centreY16_16(),m.xVelocity(),m.yVelocity(),m.groundVelocity(),m.routine(),m.angle(),m.flags(),m.spriteFlags(),m.xRadius(),m.yRadius(),m.animation(),m.previousAnimation(),m.playerJump(),m.charge(),m.moveLock(),m.stick(),0x81,m.previousPrimaryAngle(),m.previousSecondaryAngle()),h.state.animation(),h.state.header(),h.state.timers(),h.state.history(),h.state.rotationDistance(),h.state.objectLinks(),h.state.rotationAngle());var bad=new CdPlayerBody.BossSpecialContext(h.response,new CdObjectPool().capture(),255);assertTrue(h.run(bad).effects().stream().noneMatch(x->x instanceof CdPlayerBody.ObjectBossTouchResponse));}}
    private static CdPlayerBody.ObjectBossTouchResponse one(CdPlayerBody.Result r){var effects=r.effects().stream().filter(CdPlayerBody.ObjectBossTouchResponse.class::isInstance).map(CdPlayerBody.ObjectBossTouchResponse.class::cast).toList();assertEquals(1,effects.size());return effects.getFirst();}
    private static final class H {
        final CdPlayerBody body;final CdObjectPlacementRuntime pool;final CdPlayerObjectTouch scanner;final CdPlayerTouchResponse response;CdObjectPool.Snapshot cut;CdPlayerBody.TouchContext touch;CdPlayerBody.State state;CdPlayerBody.Environment env;
        H(CdR13FutureAssets a,int raw,int status){this(a,raw,status,1);}
        H(CdR13FutureAssets a,int raw,int status,int bossFight){var source=CdStagePlayerSource.fromAct3Future(a);body=CdPlayerBody.fromStageSource(source);pool=CdObjectPlacementRuntime.fromAct3FutureAssets(a,CdAssetBytes.copyOf(new byte[CdObjectPlacementRuntime.SAVED_BANK_BYTES]));var data=CdR13PlayerCollisionAssets.fromAssets(a);scanner=new CdPlayerObjectTouch(data.touchDimensions());response=CdPlayerTouchResponse.fromAct3FutureAssets(data);int x=a.initialCentre().centreX(),y=a.initialCentre().centreY();var motion=new CdPlayerMotionState(x<<16,y<<16,0x200,0x400,0,2,0,4,4,9,19,2,2,0,0,0,0,1,0,0);state=new CdPlayerBody.State(motion,new CdPlayerBody.AnimationCursor(0,0,0),new CdPlayerBody.Header(1,source.mappingAddress(),0x780,2,0x18),new CdPlayerBody.Timers(0,0,0,0),new CdPlayerBody.History(CdAssetBytes.copyOf(new byte[256]),0),0,new CdPlayerBody.ObjectLinks(0,0),0);
            env=new CdPlayerBody.Environment(new CdPlayerMovement.Environment(new CdPlayerMovement.Physics(0x600,12,0x80),new CdPlayerMovement.Bounds(0,0xD97,0x310,bossFight),new CdPlayerMovement.Gates(2,2,0,0,0,0,0),new CdPlayerMovement.Globals(0,0x60,0,0,0,0,0,0,0,0)),new CdPlayerBody.Controls(0,0,0,0,1),new CdPlayerBody.Globals(0,0,0,0,0,0,0,0),CdPlayerBody.DynamicSlots.UNIMPLEMENTED);
            pool.pool().write(pool.pool().state(50).moveByte(ID,0x2A).moveByte(SPRITE_FLAGS,0x84).moveByte(COLLISION_TYPE,raw).moveByte(COLLISION_STATUS,status).moveWord(X,x).moveWord(Y,y));refresh();}
        void refresh(){cut=pool.pool().capture();touch=new CdPlayerBody.TouchContext(scanner,cut,new CdPlayerBody.ResponseContext(response,new CdPlayerBody.ContactGlobals(0,0,0),new CdPlayerTouchResponse.WorldGlobals(10,3,0,0,5000,0)));}
        CdPlayerBody.BossSpecialContext marker(){return new CdPlayerBody.BossSpecialContext(response,cut,env.movement().bounds().bossFight());}
        CdPlayerBody.Result run(CdPlayerBody.BossSpecialContext marker){return body.step(state,env,Optional.of(touch),Optional.empty(),Optional.empty(),Optional.empty(),Optional.of(marker));}
    }
}
